with filtered_transactions as (select *, round(amount * 1.07, 2) as amount_scaled from transactions where amount < 3500 and amount >= 3300 and account_id in (4, 8, 23, 31)), agg as (select is_flagged, txn_type, count(case when merchant = 'Starbucks' then 1 end) as starbucks_count from filtered_transactions group by is_flagged, txn_type) select * from agg where starbucks_count < 10 order by starbucks_count desc;
